package org.apache.commons.codec.binary;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtils_ESTest_test20 extends StringUtils_ESTest_scaffolding {

    /**
     * Decoding four zero-bytes as UTF-16LE yields two NUL ('�') characters,
     * since UTF-16 encodes each character using two bytes.
     */
    @Test(timeout = 4000)
    public void newStringUtf16Le_decodesZeroBytesToNulCharacters() throws Throwable {
        byte[] fourZeroBytes = new byte[4];

        String decoded = StringUtils.newStringUtf16Le(fourZeroBytes);

        assertEquals("��", decoded);
    }
}
